// P1: a credential whose proof.type is not Ed25519Signature2020 skips the
// signature check entirely (verifier.rs:208). Change claims freely.
#[test]
fn p1_non_ed25519_proof_type_skips_check() {
    let store = store();
    let holder = Holder::new(1);
    let mut issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    issued.credential["expires_at"] = json!(NOW + 9999 * DAY);
    issued.credential["proof"] = json!({"type": "NoSuchProof2020"});
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let r = verifier(store).verify_presentation(&submission("r", vp), NONCE, DOMAIN);
    println!("P1 accepted with tampered expiry and no real proof: {}", r.is_ok());
}

// P2: verify_credential reads statusListIndex as u64; presenting an index
// beyond the list capacity.
#[test]
fn p2_status_index_out_of_range() {
    let store = store();
    let holder = Holder::new(1);
    let mut issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    issued.credential["credentialStatus"]["statusListIndex"] = json!(DEFAULT_CAPACITY + 5);
    // re-sign so the doctored index is covered
    let issuer = harbour();
    credentials_backend::credential::sign(&mut issued.credential, &ed25519_dalek::SigningKey::from_bytes(&seed(HARBOUR_SEED)), HARBOUR_KEY_ID, "assertionMethod", NOW);
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let _ = issuer;
    let r = verifier(store).verify_presentation(&submission("r", vp), NONCE, DOMAIN);
    println!("P2 index {} of cap {}: {:?}", DEFAULT_CAPACITY + 5, DEFAULT_CAPACITY, r.map(|v| v.credential.id).map_err(|e| format!("{e:?}")));
}

// P3: StatusList::set silently ignores an out-of-range index; the last
// allocatable index equals capacity, one past the last byte.
#[test]
fn p3_last_index_cannot_be_revoked() {
    let mut l = StatusList::new(8);
    let idxs: Vec<_> = std::iter::from_fn(|| l.allocate()).collect();
    let last = *idxs.last().unwrap();
    l.set(last, true);
    println!("P3 allocated {:?}; set({last}) then is_set({last})={}", idxs, l.is_set(last));
}

// P4: two disclosures with the same name; verifier collects into a map.
#[test]
fn p4_duplicate_disclosure_name() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    // craft a vp with two disclosures of different names both revealed, fine;
    // now reveal the same committed digest twice by duplicating one disclosure.
    let one = issued.disclosures.iter().find(|d| d.name == "tier").unwrap().clone();
    let mut vp = holder.present(&issued, &["tier"], NONCE, DOMAIN);
    vp["disclosures"] = json!([one, one]);
    // re-sign vp for the holder
    credentials_backend::credential::sign(&mut vp, &holder.key, &holder.key_id(), "authentication", NOW);
    let r = verifier(store).verify_presentation(&submission("r", vp), NONCE, DOMAIN);
    println!("P4 duplicate disclosure accepted: {:?}", r.map(|v| v.claims.len()).map_err(|e| format!("{e:?}")));
}

// P5: did_web_url percent-decodes segments; a segment could decode to contain
// a slash or dot-dot after decoding. Check what URLs come out.
#[test]
fn p5_did_web_url_decoded_traversal() {
    for did in ["did:web:h.example:%2e%2e:x", "did:web:h.example:a%2fb", "did:web:h.example:.:x"] {
        println!("P5 {did} -> {:?}", did_web_url(did));
    }
}

// P6: MirrorTransport path check — does a decoded did:web path escape root?
#[test]
fn p6_mirror_after_url_build() {
    use credentials_backend::transport::MirrorTransport;
    let m = MirrorTransport::new("/tmp/does-not-exist-root");
    for url in ["https://h.example/../../etc/passwd", "https://h.example/a%2f..%2f..%2fetc/passwd", "https://h.example/.well-known/../../../etc/passwd"] {
        println!("P6 {url} -> {:?}", m.get(url).err());
    }
}

// P7: holder proof skipped when the holder DID method is unsupported
// (verifier.rs:124). Present with a did:example holder that matches the subject.
#[test]
fn p7_unsupported_holder_method_skips_proof() {
    let store = store();
    let holder = Holder::new(1);
    let mut issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    // Reissue so the subject is a did:example the resolver can't handle.
    issued.credential["credentialSubject"]["id"] = json!("did:example:xyz");
    credentials_backend::credential::sign(&mut issued.credential, &ed25519_dalek::SigningKey::from_bytes(&seed(HARBOUR_SEED)), HARBOUR_KEY_ID, "assertionMethod", NOW);
    let mut vp = json!({
        "@context": ["https://www.w3.org/2018/credentials/v1"],
        "type": ["VerifiablePresentation"],
        "holder": "did:example:xyz",
        "verifiableCredential": issued.credential,
        "disclosures": [],
        "nonce": NONCE, "domain": DOMAIN,
        "proof": {"type": "Ed25519Signature2020", "proofValue": "zNotARealSignatureAtAll"}
    });
    let _ = &mut vp;
    let r = verifier(store).verify_presentation(&submission("r", vp), NONCE, DOMAIN);
    println!("P7 unsupported holder, bogus proof accepted: {:?}", r.map(|v| v.holder).map_err(|e| format!("{e:?}")));
}

// P8: a transport whose get() blocks would block resolve_issuer, which is
// synchronous and inside verify. Here just confirm resolve_issuer has no timeout path.
struct SlowTransport;
impl DocumentTransport for SlowTransport {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
        Err(TransportError::NotFound(url.into()))
    }
}
#[test]
fn p8_resolver_is_synchronous() {
    let v = credentials_backend::verifier::Verifier::new(Resolver::new(Arc::new(SlowTransport)), store()).with_clock(|| NOW);
    println!("P8 resolve_issuer of a did:web with no doc: {:?}", v.resolve_issuer("did:web:members.harbourclub.example").err().map(|e| format!("{e:?}")));
}
EOF
