// P9: after Ticket 1, verify_credential resolves the issuer live every call.
// Count transport.get calls per verification for an onboarded issuer.
use std::sync::atomic::{AtomicUsize, Ordering};
struct CountingTransport { inner: credentials_backend::transport::StaticTransport, n: Arc<AtomicUsize> }
impl DocumentTransport for CountingTransport {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
        self.n.fetch_add(1, Ordering::SeqCst);
        self.inner.get(url)
    }
}
#[test]
fn p9_live_resolve_count_per_verification() {
    let n = Arc::new(AtomicUsize::new(0));
    let t = CountingTransport { inner: transport(), n: n.clone() };
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let v = credentials_backend::verifier::Verifier::new(Resolver::new(Arc::new(t)), store).with_clock(|| NOW);
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let _ = v.verify_presentation(&submission("r", vp), NONCE, DOMAIN).unwrap();
    println!("P9 transport.get calls for one presentation (onboarded did:web issuer, did:key holder): {}", n.load(Ordering::SeqCst));
}
EOF
